/* From Uiverse.io by Praashoo7 - Tags: switch, torch, flashlight */
/* The switch - the box around the slider */
.__UIV_SCOPE__ .switch {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 3.8em;
  height: 3.8em;
}

.__UIV_SCOPE__ .torch {
  margin-top: 0.9em;
  margin-left: 0.95em;
  width: 30px;
  height: 30px;
  transform: rotate(-45deg);
}

.__UIV_SCOPE__ .slider .b {
  position: relative;
  top: -3.3em;
  transform: rotate(270deg);
}

.__UIV_SCOPE__ .slider .bling_85 {
  stroke: #fff;
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-dasharray: 3;
  stroke-dashoffset: 15;
  transition: all 0.3s ease;
}

/* Hide default HTML checkbox */
.__UIV_SCOPE__ .switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

/* The slider */
.__UIV_SCOPE__ .slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  transition: .4s;
  border-radius: 50%;
  background-color: rgba(116, 115, 115, 0.2);
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
  border: 1px solid rgba(255, 255, 255, 0.3);
}

.__UIV_SCOPE__ .chk_85:checked + .slider {
  animation: tap 0.3s linear forwards;
}

.__UIV_SCOPE__ .chk_85:checked + .slider .bling_85 {
  animation: bling_8561328 0.3s linear forwards;
  animation-delay: 0.2s;
}

.__UIV_SCOPE__ .chk_85:checked + .slider {
  background-color: #FFA133;
}

.__UIV_SCOPE__ .chk_85:focus + .slider {
  box-shadow: 0 0 1px #FFA133;
}

@keyframes bling_8561328 {
  50% {
    stroke-dasharray: 3;
    stroke-dashoffset: 12;
  }

  100% {
    stroke-dasharray: 3;
    stroke-dashoffset: 9;
  }
}

@keyframes tap {
  50% {
    scale: 0.9;
  }

  100% {
    scale: 1;
  }
}
